/* ===== Store & Purchase Management: store & inventory, vendors, purchase orders, budget screens + action handlers ===== */
PAGES.pr_store = { title: 'Store & Inventory', mod: 'pr_store', badge: () => pcStoreRole() ? PT().mr.filter(r => ['Approved', 'Partially issued'].includes(r.status)).length : 0, render() {
  const tx = PT(), tab = pcTab('st', 'stock'), stores = pcAllStores().filter(s => s.active && (pcCorpRole() || pcScopeBr().has(s.branch)));
  const store = App.ui.pcStore && stores.some(s => s.id === App.ui.pcStore) ? App.ui.pcStore : (stores.find(s => s.id === 'CS') || stores[0] || { id: 'CS' }).id;
  const pick = `<label class="fld"><span>Store</span><select data-act="uiSel" data-k="pcStore">${stores.map(s => `<option value="${s.id}" ${s.id === store ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}</select></label>`;
  const queue = tx.mr.filter(r => ['Approved', 'Partially issued'].includes(r.status) && pcVisible(r));
  const tabs = pcTabs('st', [['stock', 'Stock'], ['queue', 'Issue queue', queue.length], ['issues', 'Issue notes'], ['grn', 'Goods receipt'], ['moves', 'Returns & transfers', tx.moves.filter(m => m.status === 'Requested').length], ['adj', 'Adjustments & verification', tx.adjs.filter(a => a.status === 'Requested').length], ['ledger', 'Stock ledger']], 'stock');
  let body = '';
  if (tab === 'stock') {
    const rows = PM().items.filter(i => i.active || pcStock(store, i.id)).map(i => { const q = pcStock(store, i.id); return { i, q, val: q * i.rate, st: !i.reorder && store !== 'CS' ? '' : q === 0 ? 'Out of stock' : store === 'CS' && q <= i.reorder ? 'Reorder' : store === 'CS' && i.max && q > i.max ? 'Above maximum' : 'OK' }; }).filter(r => store === 'CS' || r.q > 0 || App.ui.pcAllItems);
    const T = { val: rows.reduce((a, r) => a + r.val, 0) };
    body = table('pcStock', [{ h: 'Code', k: r => r.i.code, t: 'text', cls: 'nowrap' }, { h: 'Item', k: r => r.i.name, t: 'text' }, { h: 'Category', k: r => r.isTotal ? '' : pcCat(r.i.cat) + ' · ' + r.i.sub, t: 'text', cls: 'small' }, { h: 'UoM', k: r => r.i.uom, t: 'text' }, { h: 'In stock', k: r => r.q, t: 'num', rc: r => r.st === 'Out of stock' ? 'red' : r.st === 'Reorder' ? 'amber' : '' }, { h: 'Reorder', k: r => r.i.reorder, t: 'num' }, { h: 'Min / Max', k: r => r.isTotal ? '' : `${NUM(r.i.min)} / ${NUM(r.i.max)}`, t: 'text', cls: 'small' }, { h: 'Rate', k: r => r.i.rate, t: 'inr' }, { h: 'Value', k: r => r.val, t: 'inr' }, { h: 'Tracking', k: r => (r.i.capital ? pill('Asset', 'warn') + ' ' : '') + (r.i.track ? pill(r.i.track) : ''), t: 'html', x: r => (r.i.capital ? 'Asset ' : '') + r.i.track }, { h: 'Status', k: r => r.st ? pcStatusPill(r.st) : '', t: 'html', x: r => r.st }], rows, { total: { isTotal: true, i: { code: 'Total', name: '', uom: '', sub: '', rate: null, reorder: null, capital: false, track: '' }, val: T.val, q: null, st: '' }, title: 'Stock – ' + pcStore(store).name, compact: true, limit: 100 });
    body = `<div class="kpis k4"><div class="kpi"><div class="kpi-l">Stock value</div><div class="kpi-v">${INRS(T.val)}</div><div class="kpi-s">${rows.filter(r => r.q > 0).length} items in stock</div></div><div class="kpi"><div class="kpi-l">At or below reorder</div><div class="kpi-v ${rows.some(r => r.st === 'Reorder') ? 'amber' : ''}">${rows.filter(r => r.st === 'Reorder').length}</div><div class="kpi-s">replenishment PR recommended</div></div><div class="kpi"><div class="kpi-l">Out of stock</div><div class="kpi-v ${rows.some(r => r.st === 'Out of stock') ? 'red' : ''}">${rows.filter(r => r.st === 'Out of stock').length}</div><div class="kpi-s">active items with nil balance</div></div><div class="kpi"><div class="kpi-l">Asset-tagged items</div><div class="kpi-v">${rows.filter(r => r.i.capital && r.q > 0).reduce((a, r) => a + r.q, 0)}</div><div class="kpi-s">serial / batch tracked where required · barcode scan on the mobile app</div></div></div>${body}`;
  } else if (tab === 'queue') {
    body = table('pcQueue', pcReqCols('MR').filter(c => !['Type', 'Requested by'].includes(c.h)).concat([{ h: 'Stock check', k: r => r.items.map(x => pcPend(x) ? `${esc(x.name)}: ${pcStock('CS', x.item) >= pcPend(x) ? pill('Available', 'ok') : pcStock('CS', x.item) > 0 ? pill(`Partial ${NUM(pcStock('CS', x.item))}`, 'warn') : pill('Not available', 'bad')}` : '').filter(Boolean).join('<br>'), t: 'html', x: r => r.items.map(x => `${x.name}: ${pcStock('CS', x.item)}`).join('; ') }]), queue, { rowAct: 'pcOpen', rowKey: r => r.id, compact: true, title: 'Issue queue', empty: 'No approved material requests awaiting issue.' });
  } else if (tab === 'issues') {
    const L = tx.issues.filter(n => pcCorpRole() || pcScopeBr().has(n.branch));
    body = table('pcIssues', [{ h: 'Issue note', k: n => n.no, t: 'text', cls: 'nowrap' }, { h: 'Date', k: n => isoLabel(n.date), t: 'text', x: n => n.date }, { h: 'MR', k: n => n.mrNo, t: 'text' }, { h: 'Branch', k: n => pcBr(n.branch), t: 'text' }, { h: 'Items', k: n => n.items.map(x => `${x.name} × ${x.qty}`).join(', '), t: 'text', cls: 'wrap small' }, { h: 'Value', k: n => n.items.reduce((a, x) => a + x.qty * pcItem(x.item).rate, 0), t: 'inr' }, { h: 'Issued by', k: n => n.issuedBy, t: 'text', cls: 'small' }, { h: 'Transport', k: n => n.transport, t: 'text', cls: 'small' }, { h: 'Status', k: n => pcStatusPill(n.status) + (n.ack ? `<div class="small muted">${esc(n.ack.name)} · ${tsLabel(n.ack.at)}</div>` : ''), t: 'html', x: n => n.status }, { h: '', k: n => n.ack ? '' : (can('pr_mr', 'Add') && pcScopeBr().has(n.branch) ? `<button class="btn sm" data-act="pcAckForm" data-k="${n.id}">Acknowledge</button>` : ''), t: 'html', noexp: true }], L, { compact: true, title: 'Material issue notes', limit: 100 });
  } else if (tab === 'grn') {
    const open = tx.po.filter(p => ['Issued', 'Acknowledged', 'Partially received'].includes(p.status) && (pcCorpRole() || pcScopeBr().has(p.branch)));
    const t1 = table('pcGrnOpen', [{ h: 'PO', k: p => p.no, t: 'text', cls: 'nowrap' }, { h: 'Vendor', k: p => pcVendor(p.vendor).name, t: 'text' }, { h: 'Deliver to', k: p => pcStore(p.deliverTo).name, t: 'text', cls: 'small' }, { h: 'Items', k: p => p.items.map(x => `${x.name} ${x.received}/${x.qty}`).join(', '), t: 'text', cls: 'wrap small' }, { h: 'Value', k: p => p.value, t: 'inr' }, { h: 'Delivery due', k: p => isoLabel(p.deliveryDate) + (p.deliveryDate < PROC_TODAY ? ' ' + pill('Delayed', 'bad') : ''), t: 'html', x: p => p.deliveryDate }, { h: 'Status', k: p => pcStatusPill(p.status), t: 'html', x: p => p.status }, { h: '', k: p => can('pr_store', 'Add') ? `<button class="btn sm primary" data-act="pcGRNForm" data-k="${p.id}">Create GRN</button>` : '', t: 'html', noexp: true }], open, { rowAct: 'pcPO', rowKey: p => p.id, compact: true, title: 'Purchase orders awaiting delivery', empty: 'No deliveries pending.' });
    const t2 = table('pcGrn', [{ h: 'GRN', k: g => g.no, t: 'text', cls: 'nowrap' }, { h: 'Date', k: g => isoLabel(g.date), t: 'text', x: g => g.date }, { h: 'PO', k: g => g.poNo, t: 'text' }, { h: 'Vendor', k: g => pcVendor(g.vendor).name, t: 'text' }, { h: 'Store', k: g => pcStore(g.store).name, t: 'text', cls: 'small' }, { h: 'Received', k: g => g.items.reduce((a, x) => a + x.received, 0), t: 'num' }, { h: 'Accepted', k: g => g.items.reduce((a, x) => a + x.accepted, 0), t: 'num' }, { h: 'Rejected / damaged', k: g => g.items.reduce((a, x) => a + x.rejected + x.damaged, 0), t: 'num', rc: g => g.items.some(x => x.rejected || x.damaged) ? 'red' : '' }, { h: 'Invoice', k: g => `${g.invoiceNo} · ${INR(g.invoiceValue)}`, t: 'text', cls: 'small' }, { h: 'Match', k: g => { const po = tx.po.find(p => p.id === g.poId); return po && g.invoiceValue > po.value * 1.001 ? pill('Invoice above PO', 'bad') : pill('Matched', 'ok'); }, t: 'html', x: g => { const po = tx.po.find(p => p.id === g.poId); return po && g.invoiceValue > po.value * 1.001 ? 'Invoice above PO' : 'Matched'; } }, { h: 'QC', k: g => g.qc, t: 'text', cls: 'small' }], tx.grn.filter(g => { const po = tx.po.find(p => p.id === g.poId); return pcCorpRole() || (po && pcScopeBr().has(po.branch)); }), { compact: true, title: 'Goods receipt notes', limit: 100 });
    body = card('Awaiting delivery', t1) + card('Goods receipt notes', t2, { right: exportBtns('pcGrn', 'pr_store') });
  } else if (tab === 'moves') {
    const L = tx.moves.filter(m => pcCorpRole() || pcScopeBr().has(m.branch));
    const act = m => { const a = []; if (m.status === 'Requested' && pcStoreRole() && can('pr_store', 'Approve')) { a.push(`<button class="btn sm primary" data-act="pcMoveStep" data-k="${m.id}" data-v="Approved">Approve</button><button class="btn sm danger" data-act="pcMoveStep" data-k="${m.id}" data-v="Rejected">Reject</button>`); } if (m.status === 'Approved' && can('pr_store', 'Edit')) a.push(`<button class="btn sm" data-act="pcMoveStep" data-k="${m.id}" data-v="Dispatched">Dispatch</button>`); if (m.status === 'Dispatched' && can('pr_store', 'Edit')) a.push(`<button class="btn sm primary" data-act="pcMoveStep" data-k="${m.id}" data-v="Received">Confirm receipt</button>`); return `<div class="btnstack">${a.join('')}</div>`; };
    body = table('pcMoves', [{ h: 'No.', k: m => m.no, t: 'text', cls: 'nowrap' }, { h: 'Type', k: m => m.kind, t: 'text' }, { h: 'Branch', k: m => pcBr(m.branch), t: 'text' }, { h: 'From → To', k: m => `${pcStore(m.from).name} → ${pcStore(m.to).name}`, t: 'text', cls: 'small' }, { h: 'Items', k: m => m.items.map(x => `${x.name} × ${x.qty}`).join(', '), t: 'text', cls: 'wrap small' }, { h: 'Reason', k: m => m.reason, t: 'text', cls: 'wrap small' }, { h: 'Requested', k: m => `${isoLabel(m.createdAt.slice(0, 10))} · ${m.createdByName}`, t: 'text', cls: 'small' }, { h: 'Status', k: m => pcStatusPill(m.status), t: 'html', x: m => m.status }, { h: '', k: act, t: 'html', noexp: true }], L, { compact: true, title: 'Returns, transfers, replacement and repair requests', empty: 'No movement requests.' });
    body = `<div class="btnrow">${can('pr_store', 'Add') ? '<button class="btn sm primary" data-act="pcMoveForm">New return / transfer / repair request</button>' : ''}</div>` + body;
  } else if (tab === 'adj') {
    const act = a => a.status === 'Requested' && pcStoreRole(true) && can('pr_store', 'Approve') ? `<div class="btnstack"><button class="btn sm primary" data-act="pcAdjDecide" data-k="${a.id}" data-v="Approved">Approve</button><button class="btn sm danger" data-act="pcAdjDecide" data-k="${a.id}" data-v="Rejected">Reject</button></div>` : '';
    body = `<div class="btnrow">${can('pr_store', 'Add') ? `<button class="btn sm primary" data-act="pcAdjForm" data-k="${store}">Record physical count / adjustment</button>` : ''}</div>` + table('pcAdj', [{ h: 'No.', k: a => a.no, t: 'text', cls: 'nowrap' }, { h: 'Store', k: a => pcStore(a.store).name, t: 'text', cls: 'small' }, { h: 'Item', k: a => pcItem(a.item).name, t: 'text' }, { h: 'System qty', k: a => a.system, t: 'num' }, { h: 'Counted', k: a => a.counted, t: 'num' }, { h: 'Variance', k: a => a.diff, t: 'num', rc: a => a.diff < 0 ? 'red' : a.diff > 0 ? 'amber' : '' }, { h: 'Variance value', k: a => a.diff * pcItem(a.item).rate, t: 'inr' }, { h: 'Reason', k: a => a.reason, t: 'text', cls: 'wrap small' }, { h: 'Requested by', k: a => `${a.by} · ${tsLabel(a.at)}`, t: 'text', cls: 'small' }, { h: 'Status', k: a => pcStatusPill(a.status) + (a.approver ? `<div class="small muted">${esc(a.approver)}</div>` : ''), t: 'html', x: a => a.status }, { h: '', k: act, t: 'html', noexp: true }], tx.adjs, { compact: true, title: 'Stock adjustments and physical verification' });
  } else {
    const L = tx.ledger.filter(e => e.store === store).slice(0, 400);
    body = table('pcLedger', [{ h: 'When', k: e => tsLabel(e.at), t: 'text', x: e => e.at, cls: 'nowrap' }, { h: 'Item', k: e => pcItem(e.item).name, t: 'text' }, { h: 'Movement', k: e => e.type, t: 'text' }, { h: 'Reference', k: e => e.ref, t: 'text', cls: 'small' }, { h: 'Qty', k: e => e.qty, t: 'num', rc: e => e.qty < 0 ? 'red' : '' }, { h: 'Balance', k: e => e.bal, t: 'num' }, { h: 'Value', k: e => e.qty * pcItem(e.item).rate, t: 'inr' }, { h: 'Branch', k: e => e.branch ? pcBr(e.branch) : '', t: 'text', cls: 'small' }, { h: 'By', k: e => e.by, t: 'text', cls: 'small' }, { h: 'Note', k: e => e.note || (e.n ? `${e.n} units` : ''), t: 'text', cls: 'small' }], L, { compact: true, title: 'Stock ledger – ' + pcStore(store).name, limit: 100 });
  }
  const expId = { stock: 'pcStock', queue: 'pcQueue', issues: 'pcIssues', moves: 'pcMoves', adj: 'pcAdj', ledger: 'pcLedger' }[tab];
  return `<div class="srf-strip2">${pick}<span class="grow"></span><span>${PM().cfg.allowNegative ? 'Negative stock allowed with approval' : 'Negative stock is blocked'} · stock reduces only on confirmed issue and increases only on accepted GRN</span></div>${card('Store & inventory', tabs + body, { right: expId ? exportBtns(expId, 'pr_store') : '' })}`;
} };

PAGES.pr_vendors = { title: 'Vendors & Quotations', mod: 'pr_vendors', badge: () => can('pr_vendors', 'Add') ? PT().pr.filter(p => ['Approved', 'Quotations'].includes(p.status)).length : 0, render() {
  const tx = PT(), M = PM(), tab = pcTab('vd', 'quotes');
  const prs = tx.pr.filter(p => ['Approved', 'Quotations', 'Vendor selected'].includes(p.status) && pcVisible(p));
  const tabs = pcTabs('vd', [['quotes', 'Quotations pending', prs.length], ['vendors', 'Vendor master'], ['perf', 'Vendor performance']], 'quotes');
  let body = '';
  if (tab === 'quotes') body = table('pcQPR', [{ h: 'PR', k: p => p.no, t: 'text', cls: 'nowrap' }, { h: 'Branch', k: p => pcBr(p.branch), t: 'text' }, { h: 'Category', k: p => pcCat(p.cat), t: 'text' }, { h: 'Items', k: p => pcItemsTxt(p), t: 'text', cls: 'wrap small' }, { h: 'Estimated', k: p => p.value, t: 'inr' }, { h: 'Quotations', k: p => tx.quotes.filter(q => q.prId === p.id).length, t: 'num', rc: p => tx.quotes.filter(q => q.prId === p.id).length < M.cfg.minQuotes ? 'amber' : '' }, { h: 'Approved on', k: p => isoLabel((p.approvedAt || '').slice(0, 10)), t: 'text', x: p => p.approvedAt }, { h: 'Required by', k: p => isoLabel(p.needBy), t: 'text', x: p => p.needBy }, { h: 'Status', k: p => pcStatusPill(p.status), t: 'html', x: p => p.status }, { h: '', k: p => `<button class="btn sm primary" data-act="pcQuotes" data-k="${p.id}">Quotations</button>`, t: 'html', noexp: true }], prs, { compact: true, title: 'Approved purchase requests awaiting quotations', empty: 'No approved purchase requests awaiting quotations or vendor selection.' });
  else if (tab === 'vendors') body = `<div class="btnrow">${can('pr_vendors', 'Edit') ? '<button class="btn sm primary" data-act="pcVendorForm" data-k="new">Add vendor</button>' : ''}</div>` + table('pcVend', [{ h: 'Vendor', k: x => x.name, t: 'text' }, { h: 'Contact', k: x => `${x.contact} · ${x.mobile}`, t: 'text', cls: 'small' }, { h: 'Email', k: x => x.email, t: 'text', cls: 'small' }, { h: 'Categories', k: x => x.cats.map(pcCat).join(', '), t: 'text', cls: 'wrap small' }, { h: 'Regions', k: x => x.regions.join(', '), t: 'text', cls: 'small' }, { h: 'GST', k: x => x.gst, t: 'text', cls: 'small nowrap' }, { h: 'Credit (days)', k: x => x.credit, t: 'num' }, { h: 'Rating', k: x => x.rating, t: 'num' }, { h: 'Documents', k: x => x.docs, t: 'text', cls: 'wrap small' }, { h: 'Status', k: x => pcStatusPill(x.status), t: 'html', x: x => x.status }, { h: '', k: x => can('pr_vendors', 'Edit') ? `<div class="btnstack"><button class="btn sm" data-act="pcVendorForm" data-k="${x.id}">Edit</button><button class="btn sm ghost" data-act="pcVendorTog" data-k="${x.id}">${x.status === 'Active' ? 'Deactivate' : 'Activate'}</button></div>` : '', t: 'html', noexp: true }], M.vendors, { compact: true, title: 'Approved vendor master' });
  else { const rows = M.vendors.map(vd => { const pos = tx.po.filter(p => p.vendor === vd.id && p.status !== 'Cancelled'), G = tx.grn.filter(g => g.vendor === vd.id); const late = pos.filter(p => { const g = G.filter(x => x.poId === p.id); return g.length ? g[0].date > p.deliveryDate : (p.deliveryDate < PROC_TODAY && !['Received'].includes(p.status)); }).length; const rec = G.reduce((a, g) => a + g.items.reduce((s, x) => s + x.received, 0), 0), rej = G.reduce((a, g) => a + g.items.reduce((s, x) => s + x.rejected + x.damaged, 0), 0); return { vd, pos: pos.length, val: pos.reduce((a, p) => a + p.value, 0), late, rec, rej, quotes: tx.quotes.filter(q => q.vendor === vd.id).length, won: tx.quotes.filter(q => q.vendor === vd.id && q.selected).length }; }).filter(r => r.pos || r.quotes); body = table('pcPerf', [{ h: 'Vendor', k: r => r.vd.name, t: 'text' }, { h: 'Quotations', k: r => r.quotes, t: 'num' }, { h: 'Selected', k: r => r.won, t: 'num' }, { h: 'Purchase orders', k: r => r.pos, t: 'num' }, { h: 'PO value', k: r => r.val, t: 'inr' }, { h: 'Late deliveries', k: r => r.late, t: 'num', rc: r => r.late ? 'red' : '' }, { h: 'Qty received', k: r => r.rec, t: 'num' }, { h: 'Rejected / damaged', k: r => r.rej, t: 'num', rc: r => r.rej ? 'amber' : '' }, { h: 'Quality %', k: r => r.rec ? (r.rec - r.rej) / r.rec * 100 : 100, t: 'pct' }, { h: 'Rating', k: r => r.vd.rating, t: 'num' }], rows, { compact: true, title: 'Vendor performance' }); }
  return card('Vendors & quotations', tabs + body, { right: exportBtns({ quotes: 'pcQPR', vendors: 'pcVend', perf: 'pcPerf' }[tab], 'pr_vendors'), sub: `Policy: at least ${M.cfg.minQuotes} quotations where applicable; exceptions need ${esc(M.cfg.quoteExceptionApprover)} approval and a recorded reason.` });
} };

PAGES.pr_po = { title: 'Purchase Orders', mod: 'pr_po', badge: () => pcFinRole() ? PT().po.filter(p => p.amendments.some(a => !a.approved && !a.rejected) || (p.cancel && !p.cancel.approved)).length : 0, render() {
  const tx = PT(), tab = pcTab('po', 'open'), all = tx.po.filter(p => pcCorpRole() || pcScopeBr().has(p.branch));
  const T = { open: all.filter(p => ['Issued', 'Acknowledged', 'Partially received'].includes(p.status)), late: all.filter(p => ['Issued', 'Acknowledged', 'Partially received'].includes(p.status) && p.deliveryDate < PROC_TODAY), exp: all.filter(p => ['Issued', 'Acknowledged', 'Partially received'].includes(p.status) && p.expiry <= pcAddDays(PROC_TODAY, 7)), amend: all.filter(p => p.amendments.length || p.cancel), done: all.filter(p => ['Received', 'Cancelled', 'Closed'].includes(p.status)), all };
  const tabs = pcTabs('po', [['open', 'Open', T.open.length], ['late', 'Delayed delivery', T.late.length], ['exp', 'Expiring / expired', T.exp.length], ['amend', 'Amended / cancelled', T.amend.length], ['done', 'Completed'], ['all', 'All']], 'open');
  const tb = table('pcPOs', [{ h: 'PO / LPO', k: p => p.no, t: 'text', cls: 'nowrap' }, { h: 'PR · MR', k: p => p.prNo + (p.mrNo ? ' · ' + p.mrNo : ''), t: 'text', cls: 'small nowrap' }, { h: 'Vendor', k: p => pcVendor(p.vendor).name, t: 'text' }, { h: 'Branch', k: p => pcBr(p.branch), t: 'text' }, { h: 'Items', k: p => p.items.map(x => `${x.name} ${x.received}/${x.qty}`).join(', '), t: 'text', cls: 'wrap small' }, { h: 'Value', k: p => p.value, t: 'inr' }, { h: 'Issued', k: p => isoLabel(p.createdAt.slice(0, 10)), t: 'text', x: p => p.createdAt }, { h: 'Delivery due', k: p => isoLabel(p.deliveryDate) + (p.deliveryDate < PROC_TODAY && ['Issued', 'Acknowledged', 'Partially received'].includes(p.status) ? ' ' + pill(`${pcDays(p.deliveryDate + 'T09:00:00+05:30')} d late`, 'bad') : ''), t: 'html', x: p => p.deliveryDate }, { h: 'Valid until', k: p => isoLabel(p.expiry), t: 'text', x: p => p.expiry }, { h: 'Vendor ack', k: p => p.ack ? pill('Acknowledged', 'ok') : pill('Pending', 'warn'), t: 'html', x: p => p.ack ? 'Yes' : 'No' }, { h: 'Status', k: p => pcStatusPill(p.status) + (p.amendments.length ? ` ${pill(p.amendments.length + ' amendment' + (p.amendments.length > 1 ? 's' : ''), '')}` : ''), t: 'html', x: p => p.status }], T[tab] || all, { rowAct: 'pcPO', rowKey: p => p.id, compact: true, title: 'Purchase orders', limit: 100, empty: 'No purchase orders in this view.' });
  return `<div class="note">A PO / LPO is generated only after every mandatory approval on the purchase request and vendor selection. Partial orders, several vendors per request, partial deliveries, amendment and cancellation with approval, expiry tracking and vendor acknowledgement are supported. No invoice is processed without an approved PO except approved emergency purchases.</div>${card('Purchase orders', tabs + tb, { right: exportBtns('pcPOs', 'pr_po') })}`;
} };

PAGES.pr_budget = { title: 'Budget & Finance Controls', mod: 'pr_budget', group: true, render() {
  const tx = PT(), sc = pcScopeBr(), tab = pcTab('bg', 'budget'), grp = App.f.group || 'branch';
  const rows0 = pcBudgetRows(r => (r.branch === 'CORP' ? pcCorpRole() : sc.has(r.branch)) && (!App.f.type || pcBtype(r.branch) === App.f.type));
  const keyOf = r => grp === 'branch' ? `${pcBr(r.branch)} · ${pcCat(r.cat)}` : grp === 'type' ? `${pcBtype(r.branch)} · ${pcCat(r.cat)}` : grp === 'group' ? pcCat(r.cat) : `${(pcBranch(r.branch) || {})[grp === 'zd' || grp === 'zone' ? 'zone' : 'region'] || 'Corporate'} · ${pcCat(r.cat)}`;
  const agg = new Map(); rows0.forEach(r => { const k = keyOf(r); const o = agg.get(k) || { key: k, cc: grp === 'branch' ? r.cc : '', amount: 0, committed: 0, ordered: 0, actual: 0 }; o.amount += r.amount; o.committed += r.committed; o.ordered += r.ordered; o.actual += r.actual; agg.set(k, o); });
  const rows = [...agg.values()].map(r => Object.assign(r, { used: r.committed + r.ordered, available: r.amount - r.committed - r.ordered, pct: r.amount ? (r.committed + r.ordered) / r.amount * 100 : 0 })).filter(r => r.amount || r.used);
  const tot = rows.reduce((a, r) => ({ amount: a.amount + r.amount, committed: a.committed + r.committed, ordered: a.ordered + r.ordered, actual: a.actual + r.actual }), { amount: 0, committed: 0, ordered: 0, actual: 0 });
  const T = Object.assign({ key: 'Total', cc: '' }, tot, { used: tot.committed + tot.ordered, available: tot.amount - tot.committed - tot.ordered, pct: tot.amount ? (tot.committed + tot.ordered) / tot.amount * 100 : 0 });
  const tabs = pcTabs('bg', [['budget', 'Budget vs commitment'], ['alerts', 'Budget alerts'], ['match', 'GRN & invoice matching'], ['pay', 'Vendor payables']], 'budget');
  let body = '';
  if (tab === 'budget') body = table('pcBud', [{ h: 'Budget head', k: r => r.key, t: 'text' }, { h: 'Cost centre', k: r => r.cc, t: 'text', cls: 'small nowrap' }, { h: 'Allocated 2026-27', k: r => r.amount, t: 'inr' }, { h: 'Committed (approved PR)', k: r => r.committed, t: 'inr' }, { h: 'Ordered (PO)', k: r => r.ordered, t: 'inr' }, { h: 'Actual (GRN accepted)', k: r => r.actual, t: 'inr' }, { h: 'Available', k: r => r.available, t: 'inr', rc: r => r.available < 0 ? 'red' : '' }, { h: 'Utilisation', k: r => r.pct, t: 'pct', rc: r => r.pct > 100 ? 'red' : r.pct > 85 ? 'amber' : '' }], rows, { total: T, compact: true, title: 'Budget versus commitment and actual', limit: 150 });
  else if (tab === 'alerts') {
    const A = [];
    rows0.filter(r => r.available < 0).forEach(r => A.push({ kind: 'Budget exceeded', what: `${pcBr(r.branch)} · ${pcCat(r.cat)}`, detail: `${INRS(-r.available)} over the ${INRS(r.amount)} allocation`, sev: 'bad' }));
    tx.po.filter(p => p.status !== 'Cancelled').forEach(p => { const pr = tx.pr.find(x => x.id === p.prId); if (pr && p.value > pr.value * 1.05) A.push({ kind: 'PO above approved PR', what: `${p.no} · ${pcBr(p.branch)}`, detail: `PO ${INRS(p.value)} vs PR estimate ${INRS(pr.value)} (+${PCT((p.value / pr.value - 1) * 100)})`, sev: 'warn' }); });
    tx.grn.forEach(g => { const po = tx.po.find(p => p.id === g.poId); if (po && g.invoiceValue > po.value * 1.001) A.push({ kind: 'Invoice above PO', what: `${g.no} · ${po.no}`, detail: `Invoice ${INRS(g.invoiceValue)} vs PO ${INRS(po.value)}`, sev: 'bad' }); });
    const lim = +PM().cfg.monthlyCatLimitPct || 15, ym = PROC_TODAY.slice(0, 7); const mon = {}; tx.pr.forEach(p => { if (p.branch && /Approved|Quotations|Vendor|PO|received/i.test(p.status) && (p.approvedAt || '').slice(0, 7) === ym) { const k = p.branch + '|' + p.cat; mon[k] = (mon[k] || 0) + p.value; } }); Object.entries(mon).forEach(([k, v]) => { const [b, c] = k.split('|'); const bud = pcBudgetFor(b, c); if (bud.amount && v > bud.amount * lim / 100) A.push({ kind: 'Monthly category limit', what: `${pcBr(b)} · ${pcCat(c)}`, detail: `${INRS(v)} approved this month vs ${lim}% limit (${INRS(bud.amount * lim / 100)})`, sev: 'warn' }); });
    [...tx.mr, ...tx.pr].filter(r => r.status === 'Submitted').forEach(r => pcAlerts(r).filter(a => /authority/.test(a)).forEach(a => A.push({ kind: 'Above approval authority', what: r.no, detail: a, sev: 'warn' })));
    const pr = tx.pr.filter(p => p.status === 'Submitted' && pcBudgetFor(p.branch, p.cat).amount && pcBudgetFor(p.branch, p.cat).available < p.value); pr.forEach(p => A.push({ kind: 'Request exceeds available budget', what: `${p.no} · ${pcBr(p.branch)}`, detail: `${INRS(p.value)} requested, ${INRS(pcBudgetFor(p.branch, p.cat).available)} available`, sev: 'bad' }));
    body = table('pcBAl', [{ h: 'Alert', k: a => pill(a.kind, a.sev), t: 'html', x: a => a.kind }, { h: 'Where', k: a => a.what, t: 'text' }, { h: 'Detail', k: a => a.detail, t: 'text', cls: 'wrap' }], A.filter(a => pcCorpRole() || sc.has((a.what.match(/MS [^·]+/) || [''])[0] ? [...sc].find(b => a.what.includes(pcBr(b))) : '')), { compact: true, title: 'Budget alerts', empty: 'No budget alerts.' });
  } else if (tab === 'match') body = table('pcMatch', [{ h: 'GRN', k: g => g.no, t: 'text', cls: 'nowrap' }, { h: 'PO', k: g => g.poNo, t: 'text' }, { h: 'Vendor', k: g => pcVendor(g.vendor).name, t: 'text' }, { h: 'PO value', k: g => (tx.po.find(p => p.id === g.poId) || {}).value || 0, t: 'inr' }, { h: 'GRN accepted value', k: g => { const po = tx.po.find(p => p.id === g.poId) || { items: [] }; return g.items.reduce((a, x) => { const l = po.items.find(y => y.item === x.item) || {}; return a + x.accepted * (l.rate || 0) * (1 - (l.disc || 0) / 100) * (1 + (l.tax || 0) / 100); }, 0); }, t: 'inr' }, { h: 'Invoice', k: g => g.invoiceNo || '—', t: 'text', cls: 'small' }, { h: 'Invoice value', k: g => g.invoiceValue, t: 'inr' }, { h: 'Three-way match', k: g => { const po = tx.po.find(p => p.id === g.poId); if (!g.invoiceValue) return pill('Invoice pending', 'warn'); return po && g.invoiceValue > po.value * 1.001 ? pill('Invoice above PO – hold', 'bad') : g.items.some(x => x.rejected || x.damaged) ? pill('Matched – short accepted', 'warn') : pill('Matched', 'ok'); }, t: 'html', x: g => g.invoiceValue ? 'Checked' : 'Pending' }, { h: 'Payment', k: g => { const p = tx.payments.find(x => x.grnId === g.id); return p ? pill('Paid ' + isoLabel(p.at.slice(0, 10)), 'ok') + `<div class="small muted">${esc(p.mode)} ${esc(p.ref)}</div>` : (pcFinRole() && can('pr_budget', 'Approve') && g.invoiceValue ? `<button class="btn sm primary" data-act="pcPay" data-k="${g.id}">Release payment</button>` : pill('Payable', 'warn')); }, t: 'html', x: g => tx.payments.some(x => x.grnId === g.id) ? 'Paid' : 'Payable' }], tx.grn.filter(g => { const po = tx.po.find(p => p.id === g.poId); return pcCorpRole() || (po && sc.has(po.branch)); }), { compact: true, title: 'GRN and invoice matching' });
  else { const byV = new Map(); tx.grn.forEach(g => { const o = byV.get(g.vendor) || { vendor: g.vendor, grns: 0, invoiced: 0, paid: 0 }; o.grns++; o.invoiced += g.invoiceValue; o.paid += tx.payments.filter(p => p.grnId === g.id).reduce((a, p) => a + p.amount, 0); byV.set(g.vendor, o); }); body = table('pcPay', [{ h: 'Vendor', k: r => pcVendor(r.vendor).name, t: 'text' }, { h: 'GRNs', k: r => r.grns, t: 'num' }, { h: 'Invoiced', k: r => r.invoiced, t: 'inr' }, { h: 'Paid', k: r => r.paid, t: 'inr' }, { h: 'Payable', k: r => r.invoiced - r.paid, t: 'inr', rc: r => r.invoiced - r.paid > 0 ? 'amber' : '' }, { h: 'Credit period', k: r => pcVendor(r.vendor).credit + ' days', t: 'text' }], [...byV.values()], { compact: true, title: 'Vendor payable status' }); }
  return `<div class="kpis k4"><div class="kpi"><div class="kpi-l">Allocated 2026-27</div><div class="kpi-v">${INRS(tot.amount)}</div><div class="kpi-s">${rows.length} budget heads in scope</div></div><div class="kpi"><div class="kpi-l">Committed + ordered</div><div class="kpi-v">${INRS(tot.committed + tot.ordered)}</div><div class="kpi-s">${INRS(tot.committed)} approved PRs · ${INRS(tot.ordered)} purchase orders</div></div><div class="kpi"><div class="kpi-l">Actual (GRN accepted)</div><div class="kpi-v">${INRS(tot.actual)}</div><div class="kpi-s">${tot.ordered ? PCT(tot.actual / tot.ordered * 100) : '—'} of ordered value received</div></div><div class="kpi"><div class="kpi-l">Available balance</div><div class="kpi-v ${T.available < 0 ? 'red' : ''}">${INRS(T.available)}</div><div class="kpi-s">${PCT(T.pct)} utilised</div></div></div>${card('Budget & finance controls', tabs + body, { right: exportBtns({ budget: 'pcBud', alerts: 'pcBAl', match: 'pcMatch', pay: 'pcPay' }[tab], 'pr_budget'), sub: 'Finance decisions (approve, reject, return, hold, clarification) are taken from the Approvals inbox; payment release requires PO, GRN and invoice matching except approved emergency purchases.' })}`;
} };

/* ---------- actions ---------- */
const PROC_ACT = {
  pcOpen: t => pcOpen(t.dataset.k), pcPO: t => pcPO(t.dataset.k), pcQuotes: t => pcQuotes(t.dataset.k), pcOpenRef: t => { const tx = PT(); if (pcFind(tx, t.dataset.k)) pcOpen(t.dataset.k); else if (tx.po.find(p => p.id === t.dataset.k)) pcPO(t.dataset.k); else go(t.dataset.r || 'pr_inbox'); },
  pcReadAll: async () => { const tx = Store.clone(PT()); tx.notes.forEach(n => { if (n.to.includes(App.user.id) && !(n.read || []).includes(App.user.id)) (n.read = n.read || []).push(App.user.id); }); await pcSave(tx); },
  pcNew: t => { App.ui.pcDraft = pcNewDraft(t.dataset.v); App.ui.pcCat = ''; App.ui.pcDupOk = false; pcForm(); },
  pcEdit: t => { const r = pcFind(PT(), t.dataset.k); if (!r) return; App.ui.pcDraft = Object.assign(Store.clone(r), { items: Store.clone(r.items) }); App.ui.pcDupOk = false; pcForm(); },
  pcAddLine: () => { pcSyncDraft(); const d = App.ui.pcDraft, id = v('pl_item'), qty = +v('pl_qty'), free = (v('pl_free') || '').trim(); if (!id && !free) return toast('Select an item or enter a non-stock item name.', 'bad'); if (!(qty > 0)) return toast('Enter a quantity.', 'bad'); const it = id ? pcItem(id) : { id: 'FREE-' + Date.now().toString(36), code: 'NON-STOCK', name: free, uom: 'Nos', rate: 0, cat: v('pl_cat') || 'OTH' }; const rate = v('pl_rate') ? +v('pl_rate') : it.rate; const ex = d.items.find(x => x.item === it.id); if (ex) ex.qty += qty; else d.items.push({ item: it.id, code: it.code, name: it.name, spec: (v('pl_spec') || '').trim() || it.sub || '', brand: (v('pl_brand') || '').trim(), uom: it.uom, qty, rate, issued: 0, converted: 0, cancelled: 0, received: 0, ordered: 0 }); if (!id) { const M = Store.clone(PM()); M.items.push({ id: it.id, code: it.code, name: it.name, cat: it.cat, sub: 'Non-stock', uom: 'Nos', rate, reorder: 0, min: 0, max: 0, capital: false, track: '', active: true, nonStock: true }); Store.put('proc', M); } App.ui.pcCat = v('pl_cat') || ''; pcForm(); },
  pcRmLine: t => { pcSyncDraft(); App.ui.pcDraft.items.splice(+t.dataset.k, 1); pcForm(); },
  pcSaveDraft: t => pcSaveDraft(t.dataset.v === 'submit'),
  pcSubmitOk: t => { const r = pcFind(PT(), t.dataset.k); const d = pcDupOf(r); pcRemark('Submit ' + r.no, `${r.items.length} item(s), ${INR(pcVal(r.items))}. Approval route: ${pcChain(r).map(l => l.label).join(' → ')}.${d.length ? ` <b>Possible duplicate of ${d.map(x => x.no).join(', ')}.</b>` : ''}`, false, async rem => { await pcSubmit(r.id, rem); toast(r.no + ' submitted.'); }); },
  pcDecide: t => { const r = pcFind(PT(), t.dataset.k), a = t.dataset.v; const L = r.chain[r.level]; pcRemark(`${a === 'Approve' ? 'Approve' : a === 'Reject' ? 'Reject' : a === 'Return' ? 'Return for correction' : a === 'Hold' ? 'Put on hold' : a === 'Clarify' ? 'Request clarification' : 'Release hold'} · ${r.no}`, `${L.label} level · ${pcBr(r.branch)} · ${INR(r.value)}${a === 'Approve' && r.level === r.chain.length - 1 ? ' · this is the final approval' : ''}`, a !== 'Approve', async rem => { await pcDecide(r.id, a, rem); toast(`${r.no}: ${a === 'Approve' ? 'approved' : a.toLowerCase() + 'ed'}.`.replace('Rejected', 'rejected')); }); },
  pcClarify: t => { const r = pcFind(PT(), t.dataset.k); pcRemark('Provide clarification · ' + r.no, 'Your answer is sent back to the approver.', true, rem => pcClarified(r.id, rem)); },
  pcCancel: t => { const r = pcFind(PT(), t.dataset.k); pcRemark('Cancel ' + r.no, 'The request is closed and kept in the audit history. Linked drafts are cancelled too.', true, rem => pcCancel(r.id, rem)); },
  pcRemarkOk: t => { const rem = (v('pcRem') || '').trim(); if (t.dataset.v === '1' && !rem) { const e = document.getElementById('pcRemErr'); if (e) e.hidden = false; return; } const ev = evRead(); if (ev === false) return; App.ui._evLast = ev || ''; const cb = App.ui._pcCb; App.ui._pcCb = null; closeModal(); cb && cb(rem); },
  pcIssueForm: t => pcIssueForm(t.dataset.k, 'issue'), pcUnavailForm: t => pcIssueForm(t.dataset.k, 'unavail'), pcAckForm: t => pcAckForm(t.dataset.k),
  pcIssueOk: async t => { const r = PT().mr.find(x => x.id === t.dataset.k); const lines = r.items.map(x => ({ item: x.item, qty: +(v('iq_' + x.item) || 0) })).filter(x => x.qty > 0); try { const n = await pcIssue(r.id, lines, { store: 'CS', transport: v('is_transport'), vehicle: v('is_vehicle'), remark: v('is_remark') }); closeModal(); toast(`${n.no} generated – material issued.`); } catch (e) { const el = document.getElementById('isErr'); if (el) { el.textContent = e.message; el.hidden = false; } } },
  pcUnavailOk: async t => { const r = PT().mr.find(x => x.id === t.dataset.k); const lines = r.items.map(x => ({ item: x.item, qty: +(v('iq_' + x.item) || 0) })).filter(x => x.qty > 0); try { const pr = await pcConvert(r.id, lines, v('iu_reason')); closeModal(); toast(`Purchase request ${pr.no} created / updated for the unavailable quantity.`); } catch (e) { const el = document.getElementById('isErr'); if (el) { el.textContent = e.message; el.hidden = false; } } },
  pcAckOk: async t => { const name = (v('ak_name') || '').trim(), desig = (v('ak_desig') || '').trim(), otp = (v('ak_otp') || '').trim(); if (!name || !desig) return toast('Enter the receiver name and designation.', 'bad'); if (otp && otp !== '123456') return toast('OTP does not match (demo OTP is 123456).', 'bad'); await pcAck(t.dataset.k, name, desig, !!otp); closeModal(); toast('Receipt acknowledged.'); },
  pcEnquiry: t => { const pr = PT().pr.find(p => p.id === t.dataset.k); const vs = PM().vendors.filter(x => x.status === 'Active' && x.cats.includes(pr.cat)); Store.add('emaillog', { to: vs.map(x => x.email).join(', '), subject: `Request for quotation – ${pr.no} – ${pcItemsTxt(pr).slice(0, 80)}`, trigger: 'Quotation enquiry', status: 'Simulated (not delivered)', reason: 'Microsoft 365 is not connected in this demo' }); audit('Store & Purchase', 'Quotation enquiry sent', { new: `${pr.no} → ${vs.length} vendors` }); toast(`Enquiry recorded for ${vs.length} vendors (simulated email).`); },
  pcQuoteOk: async t => { const tx = Store.clone(PT()), pr = tx.pr.find(p => p.id === t.dataset.k); const vd = v('q_vendor'); if (!vd) return toast('Select the vendor.', 'bad'); if (tx.quotes.some(q => q.prId === pr.id && q.vendor === vd)) return toast('A quotation from this vendor is already recorded for this request.', 'bad'); const items = pr.items.map(l => ({ item: l.item, qty: l.qty, rate: +v('qr_' + l.item) || 0, disc: +v('qd_' + l.item) || 0, tax: +v('qt_' + l.item) || 0 })); if (items.some(x => !(x.rate > 0))) return toast('Enter a unit rate for every item.', 'bad'); const f = document.getElementById('q_doc'); const q = { id: 'QT' + Date.now().toString(36), no: pcNo(tx, 'QT'), prId: pr.id, vendor: vd, date: v('q_date'), items, deliveryDays: +v('q_days') || 0, payTerms: v('q_pay'), warranty: v('q_war'), total: items.reduce((a, x) => a + pcLineTotal(x), 0), selected: false, justification: '', doc: f && f.files[0] ? f.files[0].name : '' }; tx.quotes.push(q); if (pr.status === 'Approved') pr.status = 'Quotations'; pcLog(pr, 'Quotation recorded', `${pcVendor(vd).name} · ${INR(q.total)}`); audit('Store & Purchase', 'Quotation recorded', { new: `${pr.no} · ${pcVendor(vd).name} · ${INR(q.total)}` }); await pcSave(tx); closeModal(); pcQuotes(pr.id); toast('Quotation saved.'); },
  pcSelectQuote: t => { const tx = PT(), q = tx.quotes.find(x => x.id === t.dataset.k), pr = tx.pr.find(p => p.id === q.prId), n = tx.quotes.filter(x => x.prId === pr.id).length, cfg = PM().cfg; pcRemark(`Select ${pcVendor(q.vendor).name} · ${INR(q.total)}`, `Justification is recorded on the request.${n < cfg.minQuotes ? ` Only ${n} quotation(s): an exception is recorded and must be approved by ${cfg.quoteExceptionApprover}; ${pcFinRole() ? 'you can approve it now' : 'it will be approved from Finance'}.` : ''}`, true, async rem => { const tx2 = Store.clone(PT()), q2 = tx2.quotes.find(x => x.id === q.id), pr2 = tx2.pr.find(p => p.id === q.prId); tx2.quotes.filter(x => x.prId === pr2.id).forEach(x => x.selected = false); q2.selected = true; q2.justification = rem; pr2.selectedVendor = q2.vendor; pr2.status = 'Vendor selected'; if (n < cfg.minQuotes) pr2.quoteException = { reason: `Fewer than ${cfg.minQuotes} quotations`, approver: pcFinRole() ? App.user.name : '', at: pcFinRole() ? nowIso() : '' }; pcLog(pr2, 'Vendor selected', `${pcVendor(q2.vendor).name} · ${INR(q2.total)} · ${rem}`); pcNotify(tx2, { users: pcRequesterUsers(pr2), text: `${pr2.no}: vendor ${pcVendor(q2.vendor).name} selected (${INRS(q2.total)})`, ref: pr2.id, route: 'pr_pr', quiet: true }); audit('Store & Purchase', 'Vendor selected', { new: `${pr2.no} · ${pcVendor(q2.vendor).name} · ${INR(q2.total)}`, reason: rem, approval: n < cfg.minQuotes ? 'Exception – ' + (pcFinRole() ? 'approved by ' + App.user.name : 'awaiting ' + cfg.quoteExceptionApprover) : '—' }); await pcSave(tx2); pcQuotes(pr2.id); }); },
  pcPOForm: t => pcPOForm(t.dataset.k),
  pcPOOk: async t => { const tx = Store.clone(PT()), pr = tx.pr.find(p => p.id === t.dataset.k), q = tx.quotes.find(x => x.prId === pr.id && x.selected); if (pr.quoteException && !pr.quoteException.approver) return toast('The quotation exception must be approved by Finance before a PO is issued.', 'bad'); if (pr.chain.some(l => l.status !== 'Approved')) return toast('Every mandatory approval must be complete before a PO is generated.', 'bad'); const items = q.items.map(x => { const l = pr.items.find(y => y.item === x.item); const qty = Math.min(+v('pq_' + x.item) || 0, l.qty - (l.ordered || 0)); return qty > 0 ? { item: x.item, name: l.name, spec: l.spec, uom: l.uom, qty, rate: x.rate, disc: x.disc, tax: x.tax, total: pcLineTotal(Object.assign({}, x, { qty })), received: 0, accepted: 0 } : null; }).filter(Boolean); if (!items.length) return toast('Enter the quantity to order.', 'bad'); const po = { id: 'PO' + Date.now().toString(36), no: pcNo(tx, 'PO'), prId: pr.id, prNo: pr.no, mrNo: pr.mrNo || '', vendor: q.vendor, branch: pr.branch, items, value: items.reduce((a, x) => a + x.total, 0), deliverTo: v('po_store'), billTo: v('po_bill'), deliveryDate: v('po_date'), payTerms: v('po_pay'), warranty: v('po_war'), terms: v('po_terms'), status: 'Issued', expiry: v('po_exp'), ack: null, amendments: [], cancel: null, approvedBy: pr.chain.map(l => `${l.label}: ${l.by}`), createdBy: App.user.name, createdAt: nowIso(), log: [] }; pcLog(po, 'Purchase order issued', pcVendor(q.vendor).name); items.forEach(x => { const l = pr.items.find(y => y.item === x.item); l.ordered = (l.ordered || 0) + x.qty; }); tx.po.unshift(po); pr.poIds.push(po.id); pr.status = 'PO issued'; pcLog(pr, `Purchase order ${po.no} issued`, `${pcVendor(q.vendor).name} · ${INR(po.value)}`); pcNotify(tx, { users: [...pcRequesterUsers(pr), ...pcUsersByRole('Store In-Charge'), ...PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r))], text: `${po.no} issued to ${pcVendor(q.vendor).name} for ${pr.no} (${INRS(po.value)}), delivery ${isoLabel(po.deliveryDate)}`, ref: po.id, route: 'pr_po' }); audit('Store & Purchase', 'Purchase order issued', { new: `${po.no} · ${pcVendor(q.vendor).name} · ${INR(po.value)} · ${pr.no}`, approval: 'All PR approvals complete' }); await pcSave(tx); closeModal(); pcPO(po.id); toast(po.no + ' issued.'); },
  pcPOAck: t => pcRemark('Record vendor acknowledgement', 'Name of the vendor contact and the mode (email, portal, signed copy).', true, async rem => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k); po.ack = { at: nowIso(), by: rem, mode: '' }; if (po.status === 'Issued') po.status = 'Acknowledged'; pcLog(po, 'Vendor acknowledgement recorded', rem); audit('Store & Purchase', 'PO acknowledged by vendor', { new: po.no, reason: rem }); await pcSave(tx); pcPO(po.id); }),
  pcAmend: t => pcRemark('Amend purchase order', `Describe the change (quantity, rate, delivery date, terms). It takes effect after approval by ${esc(PM().cfg.poAmendApprover)}.`, true, async rem => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k); po.amendments.push({ at: nowIso(), by: App.user.name, change: rem, approved: false }); pcLog(po, 'Amendment proposed', rem); pcNotify(tx, { users: PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), text: `${po.no}: amendment awaits approval – ${rem}`, ref: po.id, route: 'pr_po' }); audit('Store & Purchase', 'PO amendment proposed', { new: po.no, reason: rem, approval: 'Pending' }); await pcSave(tx); pcPO(po.id); }),
  pcAmendOk: async t => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k), a = po.amendments[+t.dataset.i]; if (!a) return; if (t.dataset.v === '1') { a.approved = true; a.approver = App.user.name; a.approvedAt = nowIso(); po.status = po.status === 'Issued' || po.status === 'Acknowledged' ? po.status : po.status; const m = a.change.match(/(\d{4}-\d{2}-\d{2})/); if (m) po.deliveryDate = m[1]; } else { a.rejected = true; a.approver = App.user.name; } pcLog(po, `Amendment ${a.approved ? 'approved' : 'rejected'}`, a.change); audit('Store & Purchase', `PO amendment ${a.approved ? 'approved' : 'rejected'}`, { new: po.no + ' · ' + a.change, approval: a.approved ? 'Approved' : 'Rejected', approver: App.user.name }); await pcSave(tx); pcPO(po.id); },
  pcPOCancel: t => pcRemark('Cancel purchase order', `Reason is mandatory; the cancellation takes effect after Finance approval${pcFinRole() ? ' (you can approve it now)' : ''}.`, true, async rem => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k); po.cancel = { reason: rem, by: App.user.name, at: nowIso(), approved: false }; pcLog(po, 'Cancellation requested', rem); pcNotify(tx, { users: PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), text: `${po.no}: cancellation awaits approval – ${rem}`, ref: po.id, route: 'pr_po' }); audit('Store & Purchase', 'PO cancellation requested', { new: po.no, reason: rem, approval: 'Pending' }); await pcSave(tx); pcPO(po.id); }),
  pcPOCancelOk: async t => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k); po.cancel.approved = true; po.cancel.approver = App.user.name; po.status = 'Cancelled'; const pr = tx.pr.find(p => p.id === po.prId); if (pr) { po.items.forEach(x => { const l = pr.items.find(y => y.item === x.item); if (l) l.ordered = Math.max(0, (l.ordered || 0) - x.qty + x.received); }); pr.status = pr.poIds.map(id => tx.po.find(p => p.id === id)).filter(p => p && p.status !== 'Cancelled').length ? pr.status : 'Vendor selected'; pcLog(pr, `Purchase order ${po.no} cancelled`, po.cancel.reason); } pcLog(po, 'Cancellation approved', ''); audit('Store & Purchase', 'PO cancelled', { old: po.no, new: 'Cancelled', reason: po.cancel.reason, approval: 'Approved', approver: App.user.name }); await pcSave(tx); pcPO(po.id); },
  pcGRNForm: t => pcGRNForm(t.dataset.k),
  pcGRNOk: async t => { const tx = Store.clone(PT()), po = tx.po.find(p => p.id === t.dataset.k), pr = tx.pr.find(p => p.id === po.prId) || { items: [] }, store = v('g_store'), date = v('g_date'); const err = m => { const e = document.getElementById('gErr2'); if (e) { e.textContent = m; e.hidden = false; } }; const items = po.items.filter(x => x.qty - x.received > 0).map(x => { const rec = +v('gr_' + x.item) || 0, rej = +v('gj_' + x.item) || 0, dam = +v('gd_' + x.item) || 0; return { item: x.item, name: x.name, received: rec, rejected: rej, damaged: dam, accepted: rec - rej - dam, note: (v('gn_' + x.item) || '').trim() }; }).filter(x => x.received > 0); if (!items.length) return err('Enter the received quantity.'); if (items.some(x => x.accepted < 0)) return err('Rejected + damaged cannot exceed the received quantity.'); if (items.some(x => (x.rejected || x.damaged) && !x.note)) return err('Enter the reason for every rejected or damaged line.'); const inv = (v('g_inv') || '').trim(), invv = +v('g_invv') || 0; if (!inv || !invv) return err('Enter the vendor invoice number and value.'); const g = { id: 'GR' + Date.now().toString(36), no: pcNo(tx, 'GRN'), poId: po.id, poNo: po.no, vendor: po.vendor, date, at: nowIso(), store, items, invoiceNo: inv, invoiceValue: invv, challan: v('g_dc'), docs: [...(document.getElementById('g_docs').files || [])].map(f => f.name).join(', '), qc: v('g_qc'), status: 'Posted', by: App.user.name }; try { items.forEach(x => { const l = po.items.find(y => y.item === x.item); l.received += x.received; l.accepted += x.accepted; if (x.accepted) pcPost(tx, store, x.item, x.accepted, 'GRN', g.no, { date, branch: pr.branch }); if (x.rejected || x.damaged) tx.ledger.unshift({ at: nowIso(), date, store, item: x.item, qty: 0, bal: pcStock(store, x.item, tx), type: x.rejected ? 'Rejected (not stocked)' : 'Damaged (not stocked)', ref: g.no, by: App.user.name, branch: pr.branch, note: x.note, n: x.rejected + x.damaged }); const pl = pr.items.find(y => y.item === x.item); if (pl) pl.received = (pl.received || 0) + x.accepted; }); } catch (e) { return err(e.message); } po.status = po.items.every(x => x.received >= x.qty) ? 'Received' : 'Partially received'; pcLog(po, `GRN ${g.no} posted`, items.map(x => `${x.name} ${x.accepted}/${x.received}`).join(', ')); if (pr.poIds) { pr.status = pr.poIds.map(id => tx.po.find(p => p.id === id)).filter(Boolean).every(p => p.status === 'Received' || p.status === 'Cancelled') ? 'Received' : 'Partially received'; pcLog(pr, `Goods received · ${g.no}`, ''); } if (pr.mrId) { const mr = tx.mr.find(m => m.id === pr.mrId); if (mr && store === pcBranchStore(mr.branch)) { items.forEach(x => { const ml = mr.items.find(y => y.item === x.item); if (ml) ml.received = (ml.received || 0) + x.accepted; }); pcRollMr(mr); pcLog(mr, `Purchased quantity delivered · ${g.no}`, ''); } } tx.grn.unshift(g); const fin = PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)); pcNotify(tx, { users: [...fin, ...pcUsersByRole('Corporate Purchase'), ...pcRequesterUsers(pr)], text: `${g.no} posted against ${po.no} (${pcVendor(po.vendor).name}) – ${items.reduce((a, x) => a + x.accepted, 0)} accepted${items.some(x => x.rejected || x.damaged) ? ', ' + items.reduce((a, x) => a + x.rejected + x.damaged, 0) + ' rejected/damaged (vendor notified)' : ''}; invoice ${inv} ${INRS(invv)}${invv > po.value * 1.001 ? ' – ABOVE PO VALUE' : ''}`, ref: po.id, route: 'pr_budget' }); audit('Store & Purchase', 'GRN posted', { new: `${g.no} · ${po.no} · ${pcStore(store).name} · invoice ${inv} ${INR(invv)}`, approval: invv > po.value * 1.001 ? 'Invoice above PO – finance hold' : 'Matched' }); await pcSave(tx); closeModal(); toast(g.no + ' posted – stock updated for the accepted quantity.'); },
  pcMoveForm: () => pcMoveForm(),
  pcMoveOk: async () => { const kind = v('mv_kind'), from = v('mv_from'), to = v('mv_to'), item = v('mv_item'), qty = +v('mv_qty'), reason = (v('mv_reason') || '').trim(); if (!item || !(qty > 0) || !reason) return toast('Select the item, quantity and reason.', 'bad'); if (from === to) return toast('From and To stores must differ.', 'bad'); if (pcStock(from, item) < qty && !PM().cfg.allowNegative) return toast(`Only ${NUM(pcStock(from, item))} in ${pcStore(from).name}.`, 'bad'); const tx = Store.clone(PT()), it = pcItem(item); const mv = { id: 'MV' + Date.now().toString(36), no: pcNo(tx, 'MV'), kind, from, to, branch: pcStore(from).branch || pcStore(to).branch || '', items: [{ item, name: it.name, uom: it.uom, qty }], reason, status: 'Requested', createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), log: [] }; pcLog(mv, 'Requested', reason); tx.moves.unshift(mv); pcNotify(tx, { users: pcUsersByRole('Store In-Charge'), text: `${mv.no}: ${kind.toLowerCase()} request from ${pcStore(from).name} – ${it.name} × ${qty}`, ref: mv.id, route: 'pr_store' }); audit('Store & Purchase', kind + ' request created', { new: `${mv.no} · ${it.name} × ${qty} · ${pcStore(from).name} → ${pcStore(to).name}`, reason }); await pcSave(tx); closeModal(); toast(mv.no + ' submitted for approval.'); },
  pcMoveStep: t => { const st = t.dataset.v; pcRemark(`${st === 'Approved' ? 'Approve' : st === 'Rejected' ? 'Reject' : st === 'Dispatched' ? 'Dispatch' : 'Confirm receipt of'} movement`, st === 'Dispatched' ? 'Enter transport / vehicle details.' : st === 'Received' ? 'Receiver name and condition of goods.' : 'Remarks are recorded in the audit trail.', st !== 'Approved', async rem => { const tx = Store.clone(PT()), mv = tx.moves.find(m => m.id === t.dataset.k); if (!mv) return; try { if (st === 'Dispatched') mv.items.forEach(x => pcPost(tx, mv.from, x.item, -x.qty, mv.kind + ' out', mv.no, { branch: mv.branch })); if (st === 'Received') mv.items.forEach(x => pcPost(tx, mv.to, x.item, x.qty, mv.kind === 'Return' ? 'Return in' : mv.kind + ' in', mv.no, { branch: mv.branch })); } catch (e) { return toast(e.message, 'bad'); } mv.status = st; pcLog(mv, st, rem); pcNotify(tx, { users: [mv.createdBy], text: `${mv.no} ${st.toLowerCase()}${rem ? ': ' + rem : ''}`, ref: mv.id, route: 'pr_store', quiet: true }); audit('Store & Purchase', `${mv.kind} ${st.toLowerCase()}`, { new: mv.no, reason: rem, approver: App.user.name }); await pcSave(tx); }); },
  pcAdjForm: t => pcAdjForm(t.dataset.k),
  pcAdjOk: async () => { const store = v('aj_store'), item = v('aj_item'), counted = +v('aj_count'), reason = (v('aj_reason') || '').trim(); if (!item || !reason) return toast('Select the item and enter the reason.', 'bad'); const sys = pcStock(store, item); if (counted === sys) return toast('Counted quantity equals the system quantity – no adjustment needed.', 'bad'); const tx = Store.clone(PT()); const a = { id: 'AJ' + Date.now().toString(36), no: pcNo(tx, 'ADJ'), store, item, counted, system: sys, diff: counted - sys, reason, status: 'Requested', by: App.user.name, approver: '', at: nowIso() }; tx.adjs.unshift(a); pcNotify(tx, { users: pcUsersByRole('Store In-Charge'), text: `${a.no}: stock adjustment ${a.diff > 0 ? '+' : ''}${a.diff} × ${pcItem(item).name} awaits approval`, ref: a.id, route: 'pr_store' }); audit('Store & Purchase', 'Stock adjustment requested', { old: `${pcItem(item).name}: ${sys}`, new: `${counted} (${a.diff > 0 ? '+' : ''}${a.diff})`, reason, approval: 'Pending' }); await pcSave(tx); closeModal(); toast(a.no + ' sent for approval.'); },
  pcAdjDecide: t => pcRemark(`${t.dataset.v === 'Approved' ? 'Approve' : 'Reject'} stock adjustment`, 'The variance is posted to the ledger on approval.', t.dataset.v !== 'Approved', async rem => { const tx = Store.clone(PT()), a = tx.adjs.find(x => x.id === t.dataset.k); if (!a) return; if (a.by === App.user.name && App.user.role !== 'Super Admin') return toast('A different user must approve the adjustment.', 'bad'); a.status = t.dataset.v; a.approver = App.user.name; a.decidedAt = nowIso(); a.decision = rem; if (a.status === 'Approved') { try { pcPost(tx, a.store, a.item, a.diff, 'Adjustment', a.no, { note: a.reason }); } catch (e) { return toast(e.message, 'bad'); } } audit('Store & Purchase', `Stock adjustment ${a.status.toLowerCase()}`, { old: `${pcItem(a.item).name}: ${a.system}`, new: a.status === 'Approved' ? String(a.counted) : 'unchanged', reason: a.reason + (rem ? ' · ' + rem : ''), approval: a.status, approver: App.user.name }); await pcSave(tx); }),
  pcPay: t => pcRemark('Release vendor payment', 'Payment is released only with an approved PO, a posted GRN and a matched invoice. Enter the payment mode and reference.', true, async rem => { const tx = Store.clone(PT()), g = tx.grn.find(x => x.id === t.dataset.k), po = tx.po.find(p => p.id === g.poId), pr = tx.pr.find(p => p.id === po.prId) || {}; if (g.invoiceValue > po.value * 1.001 && pr.priority !== 'Emergency') return toast('Invoice exceeds the PO value – amend the PO or obtain a credit note first.', 'bad'); tx.payments.push({ id: 'PY' + Date.now().toString(36), grnId: g.id, poId: po.id, vendor: g.vendor, amount: g.invoiceValue, at: nowIso(), by: App.user.name, mode: rem, ref: '' }); pcLog(po, 'Payment released', `${INR(g.invoiceValue)} · ${rem}`); audit('Store & Purchase', 'Vendor payment released', { new: `${g.no} · ${pcVendor(g.vendor).name} · ${INR(g.invoiceValue)}`, reason: rem, approval: 'PO + GRN + invoice matched', approver: App.user.name }); await pcSave(tx); }),
  pcVendorForm: t => pcVendorForm(t.dataset.k), pcVendorOk: t => pcVendorOk(t.dataset.k),
  pcVendorTog: t => askReason('Change vendor status', pcVendor(t.dataset.k).name, async r => { const M = Store.clone(PM()), x = M.vendors.find(y => y.id === t.dataset.k); x.status = x.status === 'Active' ? 'Inactive' : 'Active'; await Store.put('proc', M); audit('Store & Purchase', 'Vendor ' + x.status.toLowerCase(), { new: x.name, reason: r }); })
};
function pcVendorForm(id) {
  const x = id === 'new' ? { id: '', name: '', contact: '', mobile: '', email: '', address: '', gst: '', bank: '', cats: [], regions: [], credit: 30, rating: 4, status: 'Active', docs: '' } : pcVendor(id);
  const regions = [...new Set(DATA.branches.map(b => b.region))];
  modal(id === 'new' ? 'Add vendor' : 'Edit vendor · ' + x.name, `<div class="form-grid">${pcFld('Vendor name', `<input id="vd_name" value="${esc(x.name)}">`)}${pcFld('Contact person', `<input id="vd_contact" value="${esc(x.contact)}">`)}${pcFld('Mobile', `<input id="vd_mobile" value="${esc(x.mobile)}">`)}${pcFld('Email', `<input id="vd_email" value="${esc(x.email)}">`)}${pcFld('GST / tax registration', `<input id="vd_gst" value="${esc(x.gst)}">`)}${pcFld('Credit period (days)', `<input id="vd_credit" type="number" min="0" value="${x.credit}">`)}${pcFld('Vendor rating (0–5)', `<input id="vd_rating" type="number" min="0" max="5" step="0.1" value="${x.rating}">`)}${pcFld('Status', pcSel('vd_status', ['Active', 'Inactive'], x.status))}</div><label class="fld"><span>Address</span><input id="vd_address" value="${esc(x.address)}"></label><label class="fld"><span>Bank details</span><input id="vd_bank" value="${esc(x.bank)}" placeholder="Bank · account · IFSC"></label><div class="form-grid"><label class="fld"><span>Product / service categories</span><select id="vd_cats" multiple size="6">${PM().cats.map(c => `<option value="${c.id}" ${x.cats.includes(c.id) ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label><label class="fld"><span>Approved regions</span><select id="vd_regions" multiple size="6">${regions.map(r => `<option ${x.regions.includes(r) ? 'selected' : ''}>${esc(r)}</option>`).join('')}</select></label></div><label class="fld"><span>Supporting documents</span><input id="vd_docs" value="${esc(x.docs)}" placeholder="GST certificate, PAN, cancelled cheque…"></label>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="pcVendorOk" data-k="${id}">Save</button>`, true);
}
function pcVendorOk(id) {
  const o = { name: (v('vd_name') || '').trim(), contact: v('vd_contact'), mobile: v('vd_mobile'), email: v('vd_email'), address: v('vd_address'), gst: (v('vd_gst') || '').trim().toUpperCase(), bank: v('vd_bank'), cats: [...document.getElementById('vd_cats').selectedOptions].map(o => o.value), regions: [...document.getElementById('vd_regions').selectedOptions].map(o => o.value), credit: +v('vd_credit') || 0, rating: +v('vd_rating') || 0, status: v('vd_status'), docs: v('vd_docs') };
  if (!o.name || !o.cats.length) return toast('Enter the vendor name and at least one category.', 'bad'); if (o.gst && !/^[0-9A-Z]{15}$/.test(o.gst)) return toast('GST number must be 15 characters.', 'bad');
  const M = Store.clone(PM()); if (M.vendors.some(x => x.id !== id && (x.name.toLowerCase() === o.name.toLowerCase() || (o.gst && x.gst === o.gst)))) return toast('A vendor with this name or GST number already exists.', 'bad');
  askReason(id === 'new' ? 'Add vendor' : 'Update vendor', o.name, async r => { if (id === 'new') M.vendors.push(Object.assign({ id: 'V' + String(M.vendors.length + 1).padStart(2, '0') + Date.now().toString(36).slice(-2) }, o)); else Object.assign(M.vendors.find(x => x.id === id), o); await Store.put('proc', M); audit('Store & Purchase', id === 'new' ? 'Vendor added' : 'Vendor updated', { new: o.name + ' · ' + o.cats.map(pcCat).join(', '), reason: r }); toast('Vendor saved.'); });
}
